(function(){
 'use strict';
 const button=document.getElementById('pwa-button'),banner=document.getElementById('pwa-network-banner');
 if(!button||!banner)return;
 let installEvent=null,registration=null,copyState='Подготовка автономной копии…',updateAvailable=false,reloadRequested=false,connectionLost=false;
 const enabled=()=>{try{return localStorage.getItem('izdelie-pwa-offline')!=='0'}catch{return true}};
 const installed=()=>!!navigator.standalone||!!window.matchMedia?.('(display-mode: standalone)').matches;
 const dialog=document.createElement('dialog');dialog.className='pwa-dialog';dialog.id='pwa-dialog';dialog.setAttribute('aria-labelledby','pwa-title');document.body.append(dialog);
 function status(){button.textContent=updateAvailable?'Обновить приложение':installed()?'Приложение':'Установить приложение';banner.hidden=navigator.onLine!==false&&!connectionLost;banner.textContent=(navigator.onLine===false?'Нет сети':'Сервер недоступен')+' · расчёты и сохранение на устройстве доступны. Для синхронизации нужен интернет; после подключения проверьте «Сервер и копии».';const text=document.getElementById('pwa-copy-state');if(text)text.textContent=copyState}
 function show(){dialog.innerHTML='<div class="pwa-dialog-head"><img src="/icon-192.png" alt=""><h2 id="pwa-title">Изделие как приложение</h2><button id="pwa-close" aria-label="Закрыть настройки приложения">✕</button></div><p>Запускайте калькулятор с рабочего стола в отдельном окне.</p><div class="pwa-actions"><button class="primary" id="pwa-install">'+(installed()?'Приложение установлено':'Установить приложение')+'</button>'+(updateAvailable?'<button class="primary" id="pwa-update">Применить обновление</button>':'')+'<button id="pwa-check">Проверить обновления</button></div><p id="pwa-install-help" class="pwa-note">В Chrome или Edge используйте кнопку установки в адресной строке либо меню браузера → установка приложения. На iPhone/iPad: «Поделиться» → «На экран Домой». Во встроенном браузере установка может быть недоступна — откройте ссылку в обычном браузере.</p><div class="pwa-state" id="pwa-copy-state"></div><p class="pwa-note">Без сети работают расчёты, справочники и данные, уже сохранённые на этом устройстве. Общая база, проверка доступа и синхронизация требуют подключения. Автономная копия содержит внутренние справочники.</p><div class="pwa-actions"><button id="pwa-offline">'+(enabled()?'Удалить автономную копию':'Включить работу без сети')+'</button></div><p class="pwa-note">Удаление автономной копии не удаляет расчёты и КП. При обновлении открытые редакторы нужно сначала сохранить и закрыть.</p><p id="pwa-action-state" role="status"></p>';
 document.getElementById('pwa-close').onclick=()=>dialog.close();document.getElementById('pwa-install').onclick=install;document.getElementById('pwa-install').disabled=installed();document.getElementById('pwa-check').onclick=checkUpdate;document.getElementById('pwa-offline').onclick=toggleOffline;if(updateAvailable)document.getElementById('pwa-update').onclick=applyUpdate;status();if(!dialog.open)dialog.showModal();}
 function report(message){const node=document.getElementById('pwa-action-state');if(node)node.textContent=message}
 async function install(){if(!installEvent){report('Откройте этот сайт в Chrome или Edge и выберите установку в меню браузера.');return}const event=installEvent;installEvent=null;try{await event.prompt();const choice=await event.userChoice;report(choice.outcome==='accepted'?'Установка подтверждена. Значок появится среди приложений.':'Установку можно повторить позже.')}catch{report('Используйте установку через меню браузера.')}}
 async function checkUpdate(){if(!registration){report('Для обновления включите автономную копию и подключитесь к интернету.');return}try{await registration.update();if(registration.waiting){updateAvailable=true;show()}else report('Проверка выполнена. Новая версия появится здесь после её загрузки.')}catch{report('Не удалось проверить обновления. Проверьте подключение.')}}
 function applyUpdate(){if(document.getElementById('modal')?.open){report('Сохраните и закройте редактор позиции, затем примените обновление.');return}try{if(typeof persist==='function')persist();if(typeof saveDraft==='function')saveDraft()}catch{report('Не удалось сохранить черновик. Скачайте его перед обновлением.');return}reloadRequested=true;if(registration?.waiting)registration.waiting.postMessage({type:'APPLY_UPDATE'});else location.reload()}
 async function toggleOffline(){try{if(enabled()){localStorage.setItem('izdelie-pwa-offline','0');await registration?.unregister();for(const name of await caches.keys())if(name.startsWith('izdelie-app-'))await caches.delete(name);registration=null;copyState='Автономная копия отключена. Данные калькулятора сохранены.'}else{localStorage.setItem('izdelie-pwa-offline','1');copyState='Подготовка автономной копии…';await register()}show()}catch{report('Не удалось изменить автономную копию. Проверьте разрешения браузера.')}}
 async function register(){if(!('serviceWorker' in navigator)||!window.isSecureContext||location.protocol==='file:'){copyState='Автономная копия недоступна в этом браузере. Откройте опубликованный сайт в Chrome или Edge.';status();return}if(!enabled()){copyState='Работа без сети отключена на этом устройстве.';status();return}try{registration=await navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'});if(registration.waiting)updateAvailable=true;if(registration.active)copyState='Автономная копия готова на этом устройстве.';const watch=worker=>{if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'){if(navigator.serviceWorker.controller){updateAvailable=true}else copyState='Автономная копия готова на этом устройстве.';status();if(dialog.open)show()}if(worker.state==='redundant'){copyState='Автономная копия не подготовлена. Подключитесь к сети и повторите проверку.';status()}})};watch(registration.installing);registration.addEventListener('updatefound',()=>watch(registration.installing));navigator.serviceWorker.ready.then(()=>{copyState='Автономная копия готова на этом устройстве.';status()});status()}catch{copyState='Браузер не подготовил автономную копию. При наличии сети калькулятор работает как обычно.';status()}}
 button.onclick=()=>{if(installEvent&&!updateAvailable&&!installed())install();else show()};
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installEvent=event;status()});window.addEventListener('appinstalled',()=>{installEvent=null;status();report('Приложение установлено.')});window.addEventListener('offline',status);window.addEventListener('online',()=>{checkConnection();status();if(registration)registration.update().catch(()=>{});if(typeof connectCloud==='function'&&typeof cloudBusy!=='undefined'&&!cloudBusy)connectCloud()});
 if('serviceWorker' in navigator)navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloadRequested)location.reload();else if(registration?.active){copyState='Автономная копия готова на этом устройстве.';status()}});
 async function checkConnection(){try{await fetch('/api/health',{credentials:'same-origin',cache:'no-store',signal:typeof AbortSignal!=='undefined'?AbortSignal.timeout(6000):undefined});connectionLost=false}catch{connectionLost=true}status()}
 status();register();checkConnection();
})();
